// Read-only decomposition of frozen title abstentions; no error/gold labels.
package main
import("bufio";"encoding/json";"fmt";"os";"strconv";"strings";"openalexstats/research/country-enrichment-v3/metadata/core")
type In struct{Original core.OriginalWork `json:"original"`;Source struct{PMID,DOI,Title,Vernacular string} `json:"source"`}
type Out struct{ID uint64 `json:"id"`;Eligible bool `json:"eligible"`;Identity struct{Reason string `json:"reason"`} `json:"identity"`}
func scanner(path string)(*os.File,*bufio.Scanner){f,e:=os.Open(path);if e!=nil{panic(e)};s:=bufio.NewScanner(f);s.Buffer(make([]byte,1<<20),16<<20);return f,s}
func main(){if len(os.Args)!=4{panic("usage: title-diagnostic inputs.jsonl outcomes.jsonl summary.json")};fi,si:=scanner(os.Args[1]);defer fi.Close();fo,so:=scanner(os.Args[2]);defer fo.Close();c:=map[string]int{}
for si.Scan(){if !so.Scan(){panic("short outcome stream")};var i In;var r Out;if e:=json.Unmarshal(si.Bytes(),&i);e!=nil{panic(e)};if e:=json.Unmarshal(so.Bytes(),&r);e!=nil{panic(e)};if i.Original.ID!=r.ID{panic("input/outcome Work mismatch")};c["records"]++;collision:=strconv.FormatUint(i.Original.ID,10)==i.Source.PMID;if collision{c["numeric_work_id_equals_source_pmid_records"]++;if r.Eligible{c["eligible_numeric_equal_records"]++}}
if r.Identity.Reason!="strict_long_title_not_equal"{continue};c["title_rejected_records"]++;long:=core.LongTitle(i.Original.Title);n:=core.Normalize(i.Original.Title);same:=n==core.Normalize(i.Source.Title)||n==core.Normalize(i.Source.Vernacular);if !long{c["failed_minimum_title_length_or_token_rule"]++};if !same{c["normalized_title_different_from_both_source_titles"]++};if !long&&same{c["minimum_only_title_rejections"]++};if long&&!same{c["difference_only_title_rejections"]++};if !long&&!same{c["both_minimum_and_difference_rejections"]++};if strings.TrimSpace(i.Original.Title)==""{c["original_title_empty"]++};if collision{c["title_rejected_numeric_work_equals_source_pmid"]++;if !long{c["title_rejected_numeric_equal_below_minimum"]++};if !same{c["title_rejected_numeric_equal_different"]++};if i.Original.PMID==""{c["title_rejected_numeric_equal_original_pmid_empty"]++}}}
if si.Err()!=nil{panic(si.Err())};if so.Scan(){panic("long outcome stream")};if so.Err()!=nil{panic(so.Err())};result:=map[string]any{"status":"descriptive_readonly_indicators_not_proven_identity_errors","counts":c,"normalization_and_minimum":"Exact unchanged frozen core.LongTitle/core.Normalize","numeric_equality":"Work numeric ID equals independent source PMID; a diagnostic indicator, not causal attribution or an error label","gold_used":false,"candidate_or_rule_changed":false};b,e:=json.MarshalIndent(result,"","  ");if e!=nil{panic(e)};if e=os.WriteFile(os.Args[3],append(b,'\n'),0644);e!=nil{panic(e)};fmt.Println(string(b))}
